18	export async function runCommand<T extends ArgsDef = ArgsDef>(
19	  cmd: CommandDef<T>,
20	  opts: RunCommandOptions,
21	): Promise<{ result: unknown }> {
22	  const cmdArgs = await resolveValue(cmd.args || {});
23	  const parsedArgs = parseArgs<T>(opts.rawArgs, cmdArgs);
24	
25	  const context: CommandContext<T> = {
26	    rawArgs: opts.rawArgs,
27	    args: parsedArgs,
28	    data: opts.data,
29	    cmd,
30	  };
31	
32	  // Setup hook
33	  if (typeof cmd.setup === "function") {
34	    await cmd.setup(context);
35	  }
36	
37	  // Handle sub command
38	  let result: unknown;
39	  try {
40	    const subCommands = await resolveValue(cmd.subCommands);
41	    if (subCommands && Object.keys(subCommands).length > 0) {
42	      const subCommandArgIndex = opts.rawArgs.findIndex(
43	        (arg) => !arg.startsWith("-"),
44	      );
45	      const subCommandName = opts.rawArgs[subCommandArgIndex];
46	      if (subCommandName) {
47	        if (!subCommands[subCommandName]) {
48	          throw new CLIError(
49	            `Unknown command ${cyan(subCommandName)}`,
50	            "E_UNKNOWN_COMMAND",
51	          );
52	        }
53	        const subCommand = await resolveValue(subCommands[subCommandName]);
54	        if (subCommand) {
55	          await runCommand(subCommand, {
56	            rawArgs: opts.rawArgs.slice(subCommandArgIndex + 1),
57	          });
58	        }
59	      } else if (!cmd.run) {
60	        throw new CLIError(`No command specified.`, "E_NO_COMMAND");
61	      }
62	    }
63	
64	    // Handle main command
65	    if (typeof cmd.run === "function") {
66	      result = await cmd.run(context);
67	    }
68	  } finally {
69	    if (typeof cmd.cleanup === "function") {
70	      await cmd.cleanup(context);
71	    }
72	  }
