23	  // Build a normalized alias map where we track primary -> aliases relationships
24	  // The input format is { alias: primary } or { alias: [primary1, primary2] }
25	  // We also need to handle { primary: alias } format used by args.ts
26	  const aliasToMain: Map<string, string> = new Map();
27	  const mainToAliases: Map<string, string[]> = new Map();
28	
29	  for (const [key, value] of Object.entries(aliasMap)) {
30	    const targets = value;
31	    for (const target of targets) {
32	      // key is an alias for target
33	      aliasToMain.set(key, target);
34	      if (!mainToAliases.has(target)) {
35	        mainToAliases.set(target, []);
36	      }
37	      mainToAliases.get(target)!.push(key);
38	
39	      // Also set up reverse: target is an alias for key
40	      aliasToMain.set(target, key);
41	      if (!mainToAliases.has(key)) {
42	        mainToAliases.set(key, []);
43	      }
44	      mainToAliases.get(key)!.push(target);
45	    }
46	  }
47	
48	  // Build options for node:util parseArgs
49	  const options: Record<
50	    string,
51	    {
52	      type: "boolean" | "string";
53	      short?: string;
54	      default?: any;
55	      multiple?: boolean;
56	    }
57	  > = {};
58	
59	  // Helper to get option type
60	  function getType(name: string): "boolean" | "string" {
61	    if (booleans.has(name)) return "boolean";
62	    // Check aliases
63	    const aliases = mainToAliases.get(name) || [];
64	    for (const alias of aliases) {
65	      if (booleans.has(alias)) return "boolean";
66	    }
67	    return "string";
68	  }
69	
70	  // Collect all option names
71	  const allOptions = new Set<string>([
72	    ...booleans,
73	    ...strings,
74	    ...Object.keys(aliasMap),
75	    ...Object.values(aliasMap).flat(),
76	    ...Object.keys(defaults),
77	  ]);
