85	        default: defaults[name],
86	      };
87	    }
88	  }
89	
90	  // Add short aliases (single char)
91	  for (const [alias, main] of aliasToMain.entries()) {
92	    if (alias.length === 1 && options[main] && !options[main].short) {
93	      options[main].short = alias;
94	    }
95	  }
96	
97	  // Handle --no- prefixed arguments by preprocessing
98	  const processedArgs: string[] = [];
99	  const negatedFlags: Record<string, boolean> = {};
100	
101	  for (let i = 0; i < args.length; i++) {
102	    const arg = args[i]!;
103	
104	    if (arg === "--") {
105	      // Pass through -- and everything after
106	      processedArgs.push(...args.slice(i));
107	      break;
108	    }
109	
110	    // Handle --no-flag syntax
111	    if (arg.startsWith("--no-")) {
112	      const flagName = arg.slice(5);
113	      negatedFlags[flagName] = true;
114	      continue;
115	    }
116	
117	    processedArgs.push(arg);
118	  }
