120	  let parsed: { values: Record<string, any>; positionals: string[] };
121	
122	  try {
123	    parsed = parseArgs({
124	      args: processedArgs,
125	      options: Object.keys(options).length > 0 ? options : undefined,
126	      allowPositionals: true,
127	      strict: false,
128	    });
129	  } catch {
130	    // Fallback for parsing errors
131	    parsed = { values: {}, positionals: processedArgs };
132	  }
133	
134	  // Build result
135	  const out: Argv<T> = { _: [] as string[] } as Argv<T>;
136	
137	  // Add positionals
138	  out._ = parsed.positionals;
139	
140	  // Add parsed values
141	  for (const [key, value] of Object.entries(parsed.values)) {
142	    (out as any)[key] = value;
143	  }
144	
145	  // Apply negated flags
146	  for (const [name] of Object.entries(negatedFlags)) {
147	    (out as any)[name] = false;
