7	export function parseArgs<T extends ArgsDef = ArgsDef>(
8	  rawArgs: string[],
9	  argsDef: ArgsDef,
10	): ParsedArgs<T> {
11	  const parseOptions = {
12	    boolean: [] as string[],
13	    string: [] as string[],
14	    alias: {} as Record<string, string[]>,
15	    default: {} as Record<string, boolean | string>,
16	  } satisfies ParseOptions;
17	
18	  const args = resolveArgs(argsDef);
19	
20	  for (const arg of args) {
21	    if (arg.type === "positional") {
22	      continue;
23	    }
24	    if (arg.type === "string" || arg.type === "enum") {
25	      parseOptions.string.push(arg.name);
26	    } else if (arg.type === "boolean") {
27	      parseOptions.boolean.push(arg.name);
28	    }
29	    if (arg.default !== undefined) {
30	      parseOptions.default[arg.name] = arg.default;
31	    }
32	    if (arg.alias) {
33	      parseOptions.alias[arg.name] = arg.alias;
34	    }
35	
36	    // Add camelCase/kebab-case variants as aliases for case-insensitive matching
37	    const camelName = camelCase(arg.name);
38	    const kebabName = kebabCase(arg.name);
39	    if (camelName !== arg.name || kebabName !== arg.name) {
40	      const existingAliases = toArray(parseOptions.alias[arg.name] || []);
41	      if (camelName !== arg.name && !existingAliases.includes(camelName)) {
42	        existingAliases.push(camelName);
43	      }
44	      if (kebabName !== arg.name && !existingAliases.includes(kebabName)) {
45	        existingAliases.push(kebabName);
46	      }
47	      if (existingAliases.length > 0) {
48	        parseOptions.alias[arg.name] = existingAliases;
49	      }
50	    }
51	  }
52	
53	  const parsed = parseRawArgs(rawArgs, parseOptions);
54	  const [...positionalArguments] = parsed._;
55	
56	  const parsedArgsProxy = new Proxy(parsed, {
57	    get(target: ParsedArgs<any>, prop: string) {
58	      return target[prop] ?? target[camelCase(prop)] ?? target[kebabCase(prop)];
59	    },
60	  });
61	
62	  for (const [, arg] of args.entries()) {
63	    if (arg.type === "positional") {
64	      const nextPositionalArgument = positionalArguments.shift();
65	      if (nextPositionalArgument !== undefined) {
66	        parsedArgsProxy[arg.name] = nextPositionalArgument;
67	      } else if (arg.default === undefined && arg.required !== false) {
68	        throw new CLIError(
69	          `Missing required positional argument: ${arg.name.toUpperCase()}`,
70	          "EARG",
71	        );
72	      } else {
73	        parsedArgsProxy[arg.name] = arg.default;
74	      }
75	    } else if (arg.type === "enum") {
76	      const argument = parsedArgsProxy[arg.name];
77	      const options = arg.options || [];
78	      if (
79	        argument !== undefined &&
80	        options.length > 0 &&
81	        !options.includes(argument)
82	      ) {
83	        throw new CLIError(
84	          `Invalid value for argument: ${cyan(`--${arg.name}`)} (${cyan(argument)}). Expected one of: ${options.map((o) => cyan(o)).join(", ")}.`,
85	          "EARG",
86	        );
87	      }
88	    } else if (arg.required && parsedArgsProxy[arg.name] === undefined) {
89	      throw new CLIError(`Missing required argument: --${arg.name}`, "EARG");
90	    }
91	  }
92	
93	  return parsedArgsProxy as ParsedArgs<T>;
94	}
