96	export function resolveArgs(argsDef: ArgsDef): Arg[] {
97	  const args: Arg[] = [];
98	  for (const [name, argDef] of Object.entries(argsDef || {})) {
99	    args.push({
100	      ...argDef,
101	      name,
102	      alias: toArray((argDef as any).alias),
103	    });
104	  }
105	  return args;
106	}
